import socket
import threading
import queue


class ChatServer:
    def __init__(self, host: str = "127.0.0.1", port: int = 0):
        self.host = host
        self.port = port
        self._server_socket = None
        self._running = False
        self._lock = threading.Lock()
        self._clients = {}  # username -> client info dict
        self._accept_thread = None
        self._client_threads = []

    def start(self) -> int:
        self._server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._server_socket.bind((self.host, self.port))
        self._server_socket.listen(5)
        self._running = True
        self._accept_thread = threading.Thread(target=self._accept_loop, daemon=True)
        self._accept_thread.start()
        return self._server_socket.getsockname()[1]

    def stop(self):
        self._running = False
        if self._server_socket:
            try:
                self._server_socket.close()
            except Exception:
                pass
        # Close all client sockets
        with self._lock:
            for username, info in list(self._clients.items()):
                try:
                    info['socket'].close()
                except Exception:
                    pass
            self._clients.clear()
        # Wait for threads to finish
        if self._accept_thread:
            self._accept_thread.join(timeout=2)
        for t in self._client_threads:
            t.join(timeout=2)
        self._client_threads.clear()

    def _accept_loop(self):
        while self._running:
            try:
                client_socket, addr = self._server_socket.accept()
                client_socket.settimeout(1.0)
                t = threading.Thread(target=self._handle_client, args=(client_socket,), daemon=True)
                t.start()
                self._client_threads.append(t)
            except Exception:
                break

    def _handle_client(self, client_socket):
        username = None
        try:
            # Read first line for NAME
            line = self._read_line(client_socket)
            if line is None:
                return
            parts = line.split(' ', 1)
            if len(parts) < 2 or parts[0] != 'NAME':
                client_socket.close()
                return
            username = parts[1].strip()
            if not username:
                client_socket.close()
                return

            with self._lock:
                if username in self._clients:
                    # Name taken
                    client_socket.sendall(b"ERROR name taken\n")
                    client_socket.close()
                    return
                # Register
                self._clients[username] = {
                    'socket': client_socket,
                    'queue': queue.Queue()
                }
                # Notify other clients
                for other_name, info in self._clients.items():
                    if other_name != username:
                        info['queue'].put(f"* {username} joined\n")

            # Send OK
            client_socket.sendall(b"OK\n")

            # Start a sender thread for this client
            sender_thread = threading.Thread(target=self._sender_loop, args=(username, client_socket), daemon=True)
            sender_thread.start()

            # Read messages
            while self._running:
                line = self._read_line(client_socket)
                if line is None:
                    break
                if not line:
                    continue
                # Broadcast to other clients
                with self._lock:
                    for other_name, info in self._clients.items():
                        if other_name != username:
                            info['queue'].put(f"{username}: {line}\n")
        except Exception:
            pass
        finally:
            # Cleanup
            with self._lock:
                if username and username in self._clients:
                    del self._clients[username]
                    # Notify other clients
                    for other_name, info in self._clients.items():
                        info['queue'].put(f"* {username} left\n")
            try:
                client_socket.close()
            except Exception:
                pass

    def _sender_loop(self, username, client_socket):
        with self._lock:
            info = self._clients.get(username)
        if info is None:
            return
        q = info['queue']
        while self._running:
            try:
                msg = q.get(timeout=0.5)
                client_socket.sendall(msg.encode('utf-8'))
            except queue.Empty:
                continue
            except Exception:
                break

    def _read_line(self, sock):
        data = b""
        while True:
            try:
                chunk = sock.recv(1024)
                if not chunk:
                    return None
                data += chunk
                if b"\n" in data:
                    line, _, _ = data.partition(b"\n")
                    return line.decode('utf-8')
            except socket.timeout:
                continue
            except Exception:
                return None
